export default function ItineraryDrawer({ isOpen, onClose, collection = [], toggleCollection }) {
  const totalPrice = collection.reduce((acc, item) => acc + (Number(item.price) || 0), 0);

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <Overlay
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <DrawerWrapper
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 220 }}
          >
            <Header>
              <Title>My Collection ({collection.length})</Title>
              <CloseBtn onClick={onClose} aria-label="Close itinerary drawer">&times;</CloseBtn>
            </Header>

            <Content>
              {collection.length === 0 ? (
                <EmptyState>
                  <h4>Your collection is empty</h4>
                  <p>Save stays, experiences, and dining while exploring VicFalls One.</p>
                  <CheckoutBtn to="/discover" onClick={onClose}>
                    Explore Collection &rarr;
                  </CheckoutBtn>
                </EmptyState>
              ) : (
                <ItemsList>
                  {collection.map(item => (
                    <ItemCard key={item.id}>
                      <img src={item.image || item.images?.[0]} alt={item.name} />
                      <div className="info">
                        <div className="name">{item.name}</div>
                        <div className="meta">{item.location || item.type}</div>
                        {item.price && <div className="price">${item.price}</div>}
                      </div>
                      <RemoveItemBtn
                        onClick={() => toggleCollection(item)}
                        aria-label={`Remove ${item.name}`}
                      >
                        &times;
                      </RemoveItemBtn>
                    </ItemCard>
                  ))}
                </ItemsList>
              )}
            </Content>

            {collection.length > 0 && (
              <Footer>
                <SummaryRow>
                  <span className="label">Estimated Total</span>
                  <span className="value">${totalPrice.toLocaleString()}</span>
                </SummaryRow>
                <CheckoutBtn to="/plan" onClick={onClose}>
                  Request Complete Itinerary &rarr;
                </CheckoutBtn>
              </Footer>
            )}
          </DrawerWrapper>
        </>
      )}
    </AnimatePresence>
  );
}
