import React from 'react';
import styled from 'styled-components';

const SelectorWrapper = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid ${p => p.theme.colors.border};
  border-radius: ${p => p.theme.borderRadius.lg};
  background: ${p => p.theme.colors.background};
  padding: 0.5rem 0.75rem;
  transition: border-color 0.3s ease;

  &:focus-within {
    border-color: ${p => p.theme.colors.primary};
  }
`;

const AdjustBtn = styled.button`
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: ${p => p.theme.colors.white};
  border: 1px solid ${p => p.theme.colors.border};
  border-radius: 50%;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 16px;
  font-weight: 400;
  color: ${p => p.$disabled ? p.theme.colors.border : p.theme.colors.text};
  cursor: ${p => p.$disabled ? 'default' : 'pointer'};
  transition: all 0.2s ease;
  line-height: 1;
  padding-bottom: 1px;

  &:hover:not(:disabled) {
    border-color: ${p => p.theme.colors.primary};
    color: ${p => p.theme.colors.primary};
  }
`;

const ValueDisplay = styled.div`
  text-align: center;
  min-width: 60px;

  .count {
    font-family: ${p => p.theme.fonts.sans};
    font-size: ${p => p.theme.fontSizes.lg};
    font-weight: 600;
    color: ${p => p.theme.colors.text};
    line-height: 1;
  }

  .label {
    font-family: ${p => p.theme.fonts.sans};
    font-size: 9px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: ${p => p.theme.colors.textMuted};
    margin-top: 0.15rem;
  }
`;

export default function GuestSelector({ value, onChange, min = 1, max = 10, label = 'Guests' }) {
  const handleDecrement = () => {
    if (value > min) onChange(value - 1);
  };

  const handleIncrement = () => {
    if (value < max) onChange(value + 1);
  };

  return (
    <SelectorWrapper>
      <AdjustBtn
        onClick={handleDecrement}
        $disabled={value <= min}
        disabled={value <= min}
        aria-label={`Decrease ${label}`}
        type="button"
      >
        −
      </AdjustBtn>
      <ValueDisplay>
        <div className="count">{value}</div>
        <div className="label">{value === 1 ? label.replace(/s$/, '') : label}</div>
      </ValueDisplay>
      <AdjustBtn
        onClick={handleIncrement}
        $disabled={value >= max}
        disabled={value >= max}
        aria-label={`Increase ${label}`}
        type="button"
      >
        +
      </AdjustBtn>
    </SelectorWrapper>
  );
}
