import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import styled from 'styled-components';
import { motion } from 'framer-motion';

const CardWrapper = styled(motion.div)`
  position: relative;
`;

const CardLink = styled(Link)`
  display: block;
  background: ${p => p.theme.colors.white};
  border-radius: ${p => p.theme.borderRadius.xl};
  overflow: hidden;
  transition: all ${p => p.theme.transitions.normal};
  box-shadow: ${p => p.theme.shadows.card};
  text-decoration: none;
  color: inherit;

  &:hover {
    transform: translateY(-6px);
    box-shadow: ${p => p.theme.shadows.cardHover};

    img { transform: scale(1.06); }
    .overlay { opacity: 1; }
  }
`;

const ImageWrap = styled.div`
  position: relative;
  overflow: hidden;
  aspect-ratio: ${p => p.$aspect || '16/10'};
  background: ${p => p.theme.colors.backgroundAlt};

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.6s ease;
    opacity: ${p => p.$loaded ? 1 : 0};
  }

  .overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, transparent 40%, rgba(10, 33, 26, 0.55) 100%);
    opacity: 0;
    transition: opacity ${p => p.theme.transitions.normal};
  }
`;

const CategoryBadge = styled.span`
  position: absolute;
  top: 1rem;
  left: 1rem;
  padding: 0.35rem 0.85rem;
  background: ${p => p.theme.colors.primaryDark};
  color: ${p => p.theme.colors.white};
  font-family: ${p => p.theme.fonts.sans};
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  border-radius: ${p => p.theme.borderRadius.full};
  z-index: 2;
`;

const RatingBadge = styled.span`
  position: absolute;
  bottom: 1rem;
  right: 1rem;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.35rem 0.7rem;
  background: rgba(255, 255, 255, 0.95);
  border-radius: ${p => p.theme.borderRadius.full};
  font-family: ${p => p.theme.fonts.sans};
  font-size: 12px;
  font-weight: 600;
  color: ${p => p.theme.colors.text};
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  z-index: 2;

  svg { flex-shrink: 0; }
`;

const HeartButton = styled.button`
  position: absolute;
  top: 1rem;
  right: 1rem;
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.92);
  border: none;
  border-radius: 50%;
  font-size: 17px;
  cursor: pointer;
  z-index: 2;
  transition: all ${p => p.theme.transitions.fast};
  color: ${p => (p.$active ? '#E25555' : p.theme.colors.textMuted)};
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);

  &:hover {
    transform: scale(1.12);
    color: #E25555;
  }
`;

const Body = styled.div`
  padding: 1.5rem 1.75rem 1.75rem;
`;

const CardName = styled.h3`
  font-family: ${p => p.theme.fonts.serif};
  font-size: ${p => p.theme.fontSizes.xxl};
  font-weight: 400;
  color: ${p => p.theme.colors.text};
  line-height: 1.25;
  margin-bottom: 0.5rem;
  letter-spacing: -0.01em;
`;

const CardLocation = styled.p`
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.sm};
  color: ${p => p.theme.colors.textMuted};
  margin-bottom: 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.35rem;

  svg { flex-shrink: 0; opacity: 0.5; }
`;

const CardDesc = styled.p`
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.sm};
  color: ${p => p.theme.colors.textMuted};
  line-height: 1.6;
  margin-bottom: 1rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
`;

const CardPrice = styled.div`
  display: flex;
  align-items: baseline;
  gap: 0.3rem;

  strong {
    font-family: ${p => p.theme.fonts.sans};
    font-size: ${p => p.theme.fontSizes.lg};
    font-weight: 600;
    color: ${p => p.theme.colors.text};
  }

  span {
    font-family: ${p => p.theme.fonts.sans};
    font-size: ${p => p.theme.fontSizes.xs};
    color: ${p => p.theme.colors.textMuted};
  }
`;

const StarIcon = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor">
    <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
  </svg>
);

const MapPinIcon = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" />
    <circle cx="12" cy="10" r="3" />
  </svg>
);

export default function ListingCard({
  to,
  image,
  name,
  location,
  description,
  category,
  rating,
  price,
  priceLabel = '/ night',
  aspect,
  isSaved = false,
  onToggleSave,
  animationVariants,
}) {
  const [imgLoaded, setImgLoaded] = useState(false);
  const [inView, setInView] = useState(false);
  const imgRef = useRef(null);

  useEffect(() => {
    const el = imgRef.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { rootMargin: '200px' }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const handleHeart = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (onToggleSave) onToggleSave();
  };

  return (
    <CardWrapper variants={animationVariants} ref={imgRef}>
      <CardLink to={to}>
        <ImageWrap $aspect={aspect} $loaded={imgLoaded}>
          {inView && (
            <img
              src={image}
              alt={name}
              loading="lazy"
              onLoad={() => setImgLoaded(true)}
            />
          )}
          <div className="overlay" />
          {category && <CategoryBadge>{category}</CategoryBadge>}
          {rating && (
            <RatingBadge>
              <StarIcon />
              {rating}
            </RatingBadge>
          )}
          {onToggleSave && (
            <HeartButton
              $active={isSaved}
              onClick={handleHeart}
              aria-label={isSaved ? 'Remove from collection' : 'Save to collection'}
            >
              {isSaved ? '\u2665' : '\u2661'}
            </HeartButton>
          )}
        </ImageWrap>
        <Body>
          <CardName>{name}</CardName>
          {location && (
            <CardLocation>
              <MapPinIcon />
              {location}
            </CardLocation>
          )}
          {description && <CardDesc>{description}</CardDesc>}
          {price !== undefined && (
            <CardPrice>
              <strong>${price}</strong>
              <span>{priceLabel}</span>
            </CardPrice>
          )}
        </Body>
      </CardLink>
    </CardWrapper>
  );
}
