function CardCarousel({ slides, cardWidth, aspect, toLabel = 'Discover more' }) {
  const trackRef = useRef(null);
  const [active, setActive] = useState(0);

  const slideSpan = () => {
    const t = trackRef.current;
    if (!t) return 400;
    const card = t.querySelector('[data-slide]');
    return card ? card.offsetWidth + GAP : 400;
  };

  const scrollByCards = dir => {
    const t = trackRef.current;
    if (!t) return;
    t.scrollBy({ left: dir * slideSpan(), behavior: 'smooth' });
  };

  const handleScroll = () => {
    const t = trackRef.current;
    if (!t) return;
    setActive(Math.max(0, Math.round(t.scrollLeft / slideSpan())));
  };

  return (
    <CarouselWrap>
      <Track ref={trackRef} onScroll={handleScroll} $cardW={cardWidth}>
        {slides.map(s => (
          <SlideCard key={s.title} data-slide $aspect={aspect}>
            <Link className="title" to={s.to}>
              <div className="img-wrap">
                <img src={s.image} alt={s.title} loading="lazy" />
              </div>
              <Subtitle $noLine>{s.subtitle}</Subtitle>
              <h3>{s.title}</h3>
            </Link>
            <p className="desc">{s.copy}</p>
            <MoreLink to={s.to}>{toLabel}</MoreLink>
          </SlideCard>
        ))}
      </Track>
      <Controls>
        <ArrowBtn onClick={() => scrollByCards(-1)} aria-label="Previous">
          <ArrowLeftIcon size={14} />
        </ArrowBtn>
        <Dots>
          {slides.map((s, i) => (
            <Dot key={s.title} $active={i === active} onClick={() => {
              const t = trackRef.current;
              if (t) t.scrollTo({ left: i * slideSpan(), behavior: 'smooth' });
            }} aria-label={`Slide ${i + 1}`} />
          ))}
        </Dots>
        <ArrowBtn onClick={() => scrollByCards(1)} aria-label="Next">
          <ArrowRightIcon size={14} />
        </ArrowBtn>
      </Controls>
    </CarouselWrap>
  );
}

