import React, { useState, useRef, useEffect } from 'react';
import styled from 'styled-components';

const ImageWrapper = styled.div`
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: ${p => p.$placeholderColor || p.theme.colors.backgroundAlt};
`;

const StyledImage = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: ${p => (p.$loaded ? 1 : 0)};
  transition: opacity 0.6s cubic-bezier(0.22, 1, 0.36, 1);
`;

const Placeholder = styled.div`
  position: absolute;
  inset: 0;
  background: ${p => p.$color || p.theme.colors.backgroundAlt};
  opacity: ${p => (p.$visible ? 1 : 0)};
  transition: opacity 0.4s ease;
`;

export default function LazyImage({
  src,
  alt = '',
  placeholderColor,
  style,
  className,
  ...props
}) {
  const [loaded, setLoaded] = useState(false);
  const [inView, setInView] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.disconnect();
        }
      },
      { rootMargin: '200px' }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <ImageWrapper ref={ref} style={style} className={className} $placeholderColor={placeholderColor}>
      <Placeholder $visible={!loaded} $color={placeholderColor} />
      {inView && (
        <StyledImage
          src={src}
          alt={alt}
          $loaded={loaded}
          onLoad={() => setLoaded(true)}
          {...props}
        />
      )}
    </ImageWrapper>
  );
}
