/* ═══════════════════════════════════════════
   MAIN COMPONENT
   ═══════════════════════════════════════════ */
export default function DiningPage({ isInCollection, toggleCollection }) {
  const [cuisineFilter, setCuisineFilter] = useState('All');
  const [filterDrawerOpen, setFilterDrawerOpen] = useState(false);

  const featured = useMemo(
    () => restaurants.find(r => r.featured) || restaurants[0],
    []
  );

  const filtered = useMemo(
    () =>
      cuisineFilter === 'All'
        ? restaurants
        : restaurants.filter(r => matchesFilter(r.cuisine, cuisineFilter)),
    [cuisineFilter]
  );

  return (
    <PageWrapper>
      {/* ── 1. Hero ── */}
      <PageHero
        cssBackground="https://www.shearwatervictoriafalls.com/wp-content/uploads/2023/09/Dine-02-compressed.jpg"
        title="Where the Zambezi Meets the Table"
        subtitle="From intimate boma dinners beneath the stars to refined fine dining with panoramic views — Victoria Falls offers a culinary journey as breathtaking as the falls themselves."
      />

      {/* ── 2. Tonight's Table — Featured ── */}
      <FeaturedSection>
        <div style={{ maxWidth: 1200, margin: '0 auto', padding: '0 clamp(1rem, 3vw, 2rem)' }}>
          <FeaturedCard
            initial="hidden"
            animate="visible"
            variants={fadeIn}
          >
            <FeaturedImage>
              <img src={featured.images[0]} alt={featured.name} />
            </FeaturedImage>
            <FeaturedBody>
              <FeaturedEyebrow>Tonight's Table</FeaturedEyebrow>
              <FeaturedName>{featured.name}</FeaturedName>
              <FeaturedCuisine>{featured.cuisine}</FeaturedCuisine>
              <FeaturedDesc>{featured.description}</FeaturedDesc>
              <FeaturedMeta>
                <MetaItem>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                    <circle cx="12" cy="12" r="10" /><path d="M12 6v6l4 2" />
                  </svg>
                  {featured.openingHours}
                </MetaItem>
                <MetaItem>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" />
                  </svg>
                  ${featured.pricePerPerson} / person
                </MetaItem>
                <MetaItem>
                  <StarIcon />
                  {featured.priceRange}
                </MetaItem>
              </FeaturedMeta>
              {featured.signature && featured.signature.length > 0 && (
                <FeaturedDishes>
                  {featured.signature.map((dish, i) => (
                    <DishChip key={i}>{dish}</DishChip>
                  ))}
                </FeaturedDishes>
              )}
              <div>
                <DarkButton to={`/dining/${featured.slug}`}>
                  Reserve Table
                </DarkButton>
              </div>
            </FeaturedBody>
          </FeaturedCard>
        </div>
      </FeaturedSection>

      {/* ── 3 & 4. Filter + Grid ── */}
      <GridSection>
        <div style={{ maxWidth: 1200, margin: '0 auto', padding: '0 clamp(1rem, 3vw, 2rem)' }}>
          <FilterSection>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '0.75rem' }}>
              <Subtitle $noLine>Explore by Cuisine</Subtitle>
              <MobileFilterBtn onClick={() => setFilterDrawerOpen(true)}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                  <line x1="4" y1="6" x2="20" y2="6" />
                  <line x1="8" y1="12" x2="20" y2="12" />
                  <line x1="12" y1="18" x2="20" y2="18" />
                </svg>
                Filters
              </MobileFilterBtn>
            </div>
            <FilterBar>
              {CUISINE_FILTERS.map(cuisine => (
                <FilterPill
                  key={cuisine}
                  $active={cuisineFilter === cuisine}
                  onClick={() => setCuisineFilter(cuisine)}
                >
                  {cuisine}
                </FilterPill>
              ))}
            </FilterBar>
          </FilterSection>

          <ResultsBar>
            <HeadingH $sm>
              Our Restaurants
            </HeadingH>
            <ResultsCount>
              {filtered.length} {filtered.length === 1 ? 'restaurant' : 'restaurants'}
            </ResultsCount>
          </ResultsBar>

          {filtered.length === 0 ? (
            <EmptyState initial="hidden" animate="visible" variants={fadeIn}>
              <h3>No restaurants found</h3>
              <p>Try selecting a different cuisine category</p>
            </EmptyState>
          ) : (
            <motion.div initial="hidden" animate="visible" variants={stagger}>
              <RestaurantGrid>
                {filtered.map(rest => (
                  <motion.div key={rest.id} variants={fadeUp}>
                    <CardLink to={`/dining/${rest.slug}`}>
                      <CardImage>
                        <img src={rest.images[0]} alt={rest.name} loading="lazy" />
                        <CuisineBadge>{rest.cuisine}</CuisineBadge>
                        <PriceBadge>{rest.priceRange}</PriceBadge>
                      </CardImage>
                      <CardBody>
                        <CardName>{rest.name}</CardName>
                        <CardTagline>{rest.tagline}</CardTagline>
                        <CardDescription>{rest.description}</CardDescription>
                        {rest.signature && rest.signature.length > 0 && (
                          <CardDishes>
                            {rest.signature.slice(0, 3).map((dish, i) => (
                              <SmallDish key={i}>{dish}</SmallDish>
                            ))}
                          </CardDishes>
                        )}
                        <CardFooter>
                          <FooterMeta>
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                              <circle cx="12" cy="12" r="10" /><path d="M12 6v6l4 2" />
                            </svg>
                            {rest.openingHours}
                          </FooterMeta>
                          <ExploreLink to={`/dining/${rest.slug}`} onClick={e => e.stopPropagation()}>
                            Explore
                          </ExploreLink>
                        </CardFooter>
                      </CardBody>
                    </CardLink>
                  </motion.div>
                ))}
              </RestaurantGrid>
            </motion.div>
          )}
        </div>
      </GridSection>

      {/* ── 5. B2B CTA ── */}
      <B2BSection>
        <B2BInner>
          <motion.div
            initial={{ opacity: 0, y: 24 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: '-60px' }}
            transition={{ duration: 0.7 }}
          >
            <Subtitle $light $noLine>Private Events</Subtitle>
            <B2BTitle>Host Your Private Dinner or Event</B2BTitle>
            <B2BDesc>
              From intimate gatherings to grand celebrations, we curate bespoke
              dining experiences in some of Victoria Falls' most exclusive venues.
            </B2BDesc>
            <DarkButton to="/contact" $outline>
              Get in Touch
            </DarkButton>
          </motion.div>
        </B2BInner>
      </B2BSection>

      <FilterDrawer
        open={filterDrawerOpen}
        onClose={() => setFilterDrawerOpen(false)}
        title="Filter by Cuisine"
        categories={CUISINE_FILTERS}
        activeCategory={cuisineFilter}
        onCategoryChange={(cat) => {
          setCuisineFilter(cat);
          setFilterDrawerOpen(false);
        }}
      />
    </PageWrapper>
  );
}
