import React from 'react';
import { Link } from 'react-router-dom';
import styled from 'styled-components';
import { HeroGallery } from './Gallery';

const PageWrapper = styled.div`
  padding-top: 72px;
`;

const ContentGrid = styled.div`
  max-width: ${p => p.theme.layout.maxWidth};
  margin: 0 auto;
  padding: 3rem 1.5rem 4rem;
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 4rem;

  @media (max-width: ${p => p.theme.breakpoints.desktop}) {
    grid-template-columns: 1fr 340px;
    gap: 2.5rem;
  }

  @media (max-width: ${p => p.theme.breakpoints.tablet}) {
    grid-template-columns: 1fr;
    gap: 2rem;
    padding: 2rem 1.25rem 3rem;
  }
`;

const MainColumn = styled.main`
  min-width: 0;
`;

const Breadcrumbs = styled.nav`
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.sm};
  color: ${p => p.theme.colors.textMuted};
  margin-bottom: 1.25rem;

  a {
    color: ${p => p.theme.colors.cocoa};
    text-decoration: none;
    transition: color ${p => p.theme.transitions.fast};

    &:hover {
      color: ${p => p.theme.colors.primary};
      text-decoration: underline;
    }
  }

  span {
    margin: 0 0.5rem;
  }
`;

const CategoryLabel = styled.span`
  display: inline-block;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: ${p => p.theme.colors.cocoa};
  font-weight: 600;
  margin-bottom: 0.5rem;
`;

const DetailTitle = styled.h1`
  font-family: ${p => p.theme.fonts.serif};
  font-size: clamp(2.2rem, 4.5vw, 3.5rem);
  font-weight: 300;
  color: ${p => p.theme.colors.primaryDark};
  margin: 0.25rem 0 0.75rem;
  line-height: 1.1;
  letter-spacing: -0.02em;
`;

const DetailTagline = styled.p`
  font-family: ${p => p.theme.fonts.serif};
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  font-style: italic;
  font-weight: 300;
  color: ${p => p.theme.colors.textLight};
  margin-bottom: 1.75rem;
  line-height: 1.4;
`;

const MetaBar = styled.div`
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
  padding-bottom: 1.75rem;
  border-bottom: 1px solid ${p => p.theme.colors.border};
`;

const ReviewsContainer = styled.div`
  max-width: ${p => p.theme.layout.maxWidthNarrow};
  margin: 0 auto;
  padding: 0 1.5rem 4rem;
`;

export default function EditorialDetailLayout({
  images = [],
  backTo = '/discover',
  backLabel = 'Back',
  breadcrumbs = [],
  category,
  title,
  tagline,
  meta,
  sidebar,
  children,
  reviews,
}) {
  return (
    <PageWrapper>
      {images.length > 0 && (
        <HeroGallery
          images={images}
          backTo={backTo}
          backLabel={backLabel}
          alt={title}
        />
      )}

      <ContentGrid>
        <MainColumn>
          {breadcrumbs.length > 0 && (
            <Breadcrumbs aria-label="Breadcrumb">
              {breadcrumbs.map((crumb, idx) => (
                <React.Fragment key={idx}>
                  {crumb.to ? (
                    <Link to={crumb.to}>{crumb.label}</Link>
                  ) : (
                    <span>{crumb.label}</span>
                  )}
                  {idx < breadcrumbs.length - 1 && <span>&middot;</span>}
                </React.Fragment>
              ))}
            </Breadcrumbs>
          )}

          {category && <CategoryLabel>{category}</CategoryLabel>}
          {title && <DetailTitle>{title}</DetailTitle>}
          {tagline && <DetailTagline>{tagline}</DetailTagline>}
          {meta && <MetaBar>{meta}</MetaBar>}

          {children}
        </MainColumn>

        {sidebar}
      </ContentGrid>

      {reviews && <ReviewsContainer>{reviews}</ReviewsContainer>}
    </PageWrapper>
  );
}

export { Breadcrumbs, CategoryLabel, DetailTitle, DetailTagline, MetaBar };
