import React from 'react';
import styled, { css, keyframes } from 'styled-components';

const shimmer = keyframes`
  0% { background-position: -400px 0; }
  100% { background-position: 400px 0; }
`;

const shimmerBg = css`
  background: linear-gradient(
    90deg,
    ${p => p.theme.colors.backgroundAlt} 0%,
    ${p => p.theme.colors.borderLight} 40%,
    ${p => p.theme.colors.backgroundAlt} 80%
  );
  background-size: 800px 100%;
  animation: ${shimmer} 1.8s ease-in-out infinite;
`;

const Card = styled.div`
  background: ${p => p.theme.colors.white};
  border-radius: ${p => p.theme.borderRadius.xl};
  overflow: hidden;
  box-shadow: ${p => p.theme.shadows.card};
`;

const ImagePlaceholder = styled.div`
  aspect-ratio: ${p => p.$aspect || '16/10'};
  ${shimmerBg}
`;

const Body = styled.div`
  padding: 1.5rem 1.75rem 1.75rem;
`;

const Line = styled.div`
  height: ${p => p.$height || '14px'};
  width: ${p => p.$width || '100%'};
  border-radius: 4px;
  margin-bottom: ${p => p.$mb || '0.75rem'};
  ${shimmerBg}
`;

const LineRow = styled.div`
  display: flex;
  gap: 0.5rem;
  align-items: center;
`;

export default function SkeletonCard({ aspect = '16/10', count = 1 }) {
  const cards = Array.from({ length: count }, (_, i) => i);

  return (
    <>
      {cards.map((_, i) => (
        <Card key={i}>
          <ImagePlaceholder $aspect={aspect} />
          <Body>
            <Line $width="40%" $height="10px" $mb="0.5rem" />
            <Line $width="85%" $height="18px" $mb="0.5rem" />
            <Line $width="60%" $height="12px" $mb="0.75rem" />
            <Line $width="100%" $height="12px" $mb="1rem" />
            <LineRow>
              <Line $width="50px" $height="14px" $mb="0" />
              <Line $width="70px" $height="10px" $mb="0" />
            </LineRow>
          </Body>
        </Card>
      ))}
    </>
  );
}
