import { Link } from 'react-router-dom';
import styled, { css } from 'styled-components';

export const MoreLink = styled(Link)`
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 11px;
  font-weight: ${p => p.theme.fontWeights.semibold};
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: ${p => (p.$light ? 'rgba(255,255,255,0.92)' : p.theme.colors.text)};
  padding-bottom: 7px;
  transition: all ${p => p.theme.transitions.normal};

  &::after {
    content: '';
    position: absolute;
    left: 0;
    bottom: 0;
    width: 100%;
    height: 1px;
    background: currentColor;
    opacity: 0.35;
    transition: opacity 0.4s ease, transform 0.4s ease;
    transform-origin: left;
  }

  &:hover {
    color: ${p => (p.$light ? p.theme.colors.champagneLight : p.theme.colors.cocoa)};
    gap: 0.75rem;
  }
  &:hover::after { opacity: 1; }
`;

export const DarkButton = styled(Link)`
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: ${p => (p.$outline ? 'transparent' : p.theme.colors.primaryDark)};
  color: ${p => (p.$outline ? p.theme.colors.primaryDark : p.theme.colors.white)};
  font-family: ${p => p.theme.fonts.sans};
  font-size: 10px;
  font-weight: ${p => p.theme.fontWeights.semibold};
  letter-spacing: 0.24em;
  text-transform: uppercase;
  padding: 1rem 2rem;
  border-radius: ${p => p.theme.borderRadius.full};
  white-space: nowrap;
  transition: all ${p => p.theme.transitions.normal};
  ${p => p.$outline && css`
    border: 1px solid ${p.theme.colors.primaryDark};
  `}

  &:hover {
    background: ${p => (p.$outline ? p.theme.colors.primaryDark : p.theme.colors.primary)};
    color: ${p => p.theme.colors.white};
    transform: translateY(-1px);
    box-shadow: ${p => p.theme.shadows.md};
  }
`;

const Buttons = {
  MoreLink,
  DarkButton,
};

export default Buttons;
