import React from 'react';
import styled from 'styled-components';

const SidebarWrapper = styled.aside`
  @media (max-width: ${p => p.theme.breakpoints.tablet}) {
    order: -1;
  }
`;

const StickyCard = styled.div`
  position: sticky;
  top: 96px;
  background: ${p => p.theme.colors.white};
  border: 1px solid ${p => p.theme.colors.border};
  border-radius: ${p => p.theme.borderRadius.xl};
  padding: 2rem;
  box-shadow: ${p => p.theme.shadows.card};
`;

const PriceRow = styled.div`
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  margin-bottom: 1.5rem;

  strong {
    font-family: ${p => p.theme.fonts.sans};
    font-size: ${p => p.theme.fontSizes.xxl};
    font-weight: 600;
    color: ${p => p.theme.colors.primaryDark};
  }

  span {
    font-family: ${p => p.theme.fonts.sans};
    font-size: ${p => p.theme.fontSizes.md};
    color: ${p => p.theme.colors.textMuted};
  }
`;

const InputGroup = styled.div`
  margin-bottom: 1rem;

  label {
    display: block;
    font-family: ${p => p.theme.fonts.sans};
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 0.4rem;
    color: ${p => p.theme.colors.text};
  }
`;

const PrimaryBtn = styled.button`
  width: 100%;
  padding: 1rem;
  background: ${p => p.theme.colors.primaryDark};
  color: ${p => p.theme.colors.white};
  font-family: ${p => p.theme.fonts.sans};
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  border-radius: ${p => p.theme.borderRadius.full};
  margin-top: 0.5rem;
  transition: all ${p => p.theme.transitions.normal};
  border: none;
  cursor: pointer;

  &:hover {
    background: ${p => p.theme.colors.primary};
    transform: translateY(-1px);
    box-shadow: ${p => p.theme.shadows.md};
  }
`;

const SecondaryBtn = styled.button`
  width: 100%;
  padding: 0.85rem;
  background: transparent;
  border: 1px solid ${p => p.theme.colors.border};
  border-radius: ${p => p.theme.borderRadius.full};
  color: ${p => p.theme.colors.text};
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.sm};
  font-weight: 500;
  margin-top: 0.75rem;
  cursor: pointer;
  transition: all ${p => p.theme.transitions.fast};

  &:hover {
    border-color: ${p => p.theme.colors.primary};
    color: ${p => p.theme.colors.primary};
  }
`;

const LinksSection = styled.div`
  margin-top: 1.75rem;
  padding-top: 1.25rem;
  border-top: 1px solid ${p => p.theme.colors.borderLight};

  h4 {
    font-family: ${p => p.theme.fonts.sans};
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: ${p => p.theme.colors.textMuted};
    margin-bottom: 0.75rem;
  }
`;

export default function StickySidebar({
  price,
  priceLabel = '/ night',
  onBook,
  bookBtnText = 'Check Availability',
  isSaved,
  onToggleSave,
  children,
  relatedLinks,
}) {
  return (
    <SidebarWrapper>
      <StickyCard>
        {price !== undefined && (
          <PriceRow>
            <strong>${price}</strong>
            <span>{priceLabel}</span>
          </PriceRow>
        )}

        {children}

        <PrimaryBtn onClick={onBook}>{bookBtnText}</PrimaryBtn>

        {onToggleSave && (
          <SecondaryBtn onClick={onToggleSave}>
            {isSaved ? '\u2665 Saved to Collection' : '\u2661 Save to Collection'}
          </SecondaryBtn>
        )}

        {relatedLinks && (
          <LinksSection>
            <h4>{relatedLinks.title || 'You May Also Like'}</h4>
            {relatedLinks.render}
          </LinksSection>
        )}
      </StickyCard>
    </SidebarWrapper>
  );
}

export { InputGroup };
