import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import styled from 'styled-components';
import { experiences, accommodations, restaurants } from '../data/data';
import ReviewsSection from '../components/ReviewsSection';
import EditorialDetailLayout from '../components/ui/EditorialDetailLayout';
import StickySidebar, { InputGroup } from '../components/ui/StickySidebar';
import DateRangePicker from '../components/ui/DateRangePicker';
import GuestSelector from '../components/ui/GuestSelector';

const Section = styled.section`
  margin-bottom: 3rem;

  h2 {
    font-family: ${p => p.theme.fonts.serif};
    font-size: ${p => p.theme.fontSizes.xxl};
    font-weight: 400;
    margin-bottom: 1.25rem;
    color: ${p => p.theme.colors.primaryDark};
  }

  p {
    font-family: ${p => p.theme.fonts.sans};
    font-size: ${p => p.theme.fontSizes.md};
    color: ${p => p.theme.colors.textLight};
    line-height: 1.85;
    white-space: pre-line;
    font-weight: 300;
  }
`;

const IncludesList = styled.ul`
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;

  @media (max-width: ${p => p.theme.breakpoints.mobile}) {
    grid-template-columns: 1fr;
  }

  li {
    padding: 0.85rem 1.1rem;
    background: ${p => p.theme.colors.backgroundAlt};
    border-radius: ${p => p.theme.borderRadius.md};
    font-family: ${p => p.theme.fonts.sans};
    font-size: ${p => p.theme.fontSizes.sm};
    color: ${p => p.theme.colors.text};
    display: flex;
    align-items: center;
    gap: 0.5rem;

    &::before {
      content: '✓';
      color: ${p => p.theme.colors.cocoa};
      font-weight: 600;
    }
  }
`;

const MetaItem = styled.div`
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.sm};
  color: ${p => p.theme.colors.textMuted};

  strong {
    display: block;
    font-size: ${p => p.theme.fontSizes.md};
    color: ${p => p.theme.colors.text};
    font-weight: 600;
    margin-bottom: 0.15rem;
  }
`;

const RelatedCard = styled(Link)`
  display: flex;
  gap: 1rem;
  padding: 1rem;
  border: 1px solid ${p => p.theme.colors.border};
  border-radius: ${p => p.theme.borderRadius.lg};
  text-decoration: none;
  color: inherit;
  transition: all ${p => p.theme.transitions.fast};

  img {
    width: 80px;
    height: 60px;
    object-fit: cover;
    border-radius: ${p => p.theme.borderRadius.md};
  }

  &:hover {
    border-color: ${p => p.theme.colors.primary};
  }

  .title {
    font-family: ${p => p.theme.fonts.serif};
    font-size: 1.1rem;
    font-weight: 500;
    margin-bottom: 0.2rem;
    color: ${p => p.theme.colors.primaryDark};
  }

  .sub {
    font-family: ${p => p.theme.fonts.sans};
    font-size: 0.8rem;
    color: ${p => p.theme.colors.textMuted};
  }
`;

export default function ExperienceDetailPage({ isInCollection, toggleCollection }) {
  const { slug } = useParams();
  const [selectedDate, setSelectedDate] = useState(null);
  const [guests, setGuests] = useState(2);

  const exp = experiences.find(e => e.slug === slug);

  if (!exp) {
    return (
      <div style={{ textAlign: 'center', padding: '10rem 2rem' }}>
        <h1 style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '2.5rem', marginBottom: '1rem' }}>
          Experience not found
        </h1>
        <Link to="/experiences" style={{ color: '#7C5E3F', textDecoration: 'underline' }}>
          Back to Experiences
        </Link>
      </div>
    );
  }

  const isSaved = isInCollection ? isInCollection(exp.id) : false;

  const handleBook = () => {
    alert(`Booking initiated for ${exp.name}`);
  };

  const handleSave = () => {
    if (toggleCollection) {
      toggleCollection({
        id: exp.id,
        type: 'experience',
        name: exp.name,
        image: exp.images[0],
        price: exp.price,
      });
    }
  };

  return (
    <EditorialDetailLayout
      images={exp.images}
      backTo="/experiences"
      backLabel="Back to Experiences"
      breadcrumbs={[
        { label: 'Discover', to: '/discover' },
        { label: 'Experiences', to: '/experiences' },
        { label: exp.name },
      ]}
      category={exp.category}
      title={exp.name}
      tagline={exp.tagline}
      meta={
        <>
          <MetaItem>
            <strong>{exp.duration}</strong>Duration
          </MetaItem>
          <MetaItem>
            <strong>★ {exp.rating}</strong>{exp.reviewCount} reviews
          </MetaItem>
          <MetaItem>
            <strong>{exp.groupSize || 'Small group'}</strong>Group size
          </MetaItem>
        </>
      }
      sidebar={
        <StickySidebar
          price={exp.price}
          priceLabel="/ person"
          onBook={handleBook}
          bookBtnText="Book Experience"
          isSaved={isSaved}
          onToggleSave={handleSave}
          relatedLinks={{
            title: 'Similar Experiences',
            render: experiences
              .filter(e => e.id !== exp.id && e.category === exp.category)
              .slice(0, 3)
              .map(e => (
                <Link
                  key={e.id}
                  to={`/experiences/${e.slug}`}
                  style={{
                    display: 'block',
                    padding: '0.5rem 0',
                    fontSize: '0.85rem',
                    color: '#7C5E3F',
                    textDecoration: 'none',
                  }}
                >
                  {e.name}
                </Link>
              )),
          }}
        >
          <InputGroup>
            <label>Preferred Date</label>
            <DateRangePicker
              startDate={selectedDate}
              endDate={null}
              onChange={(dates) => setSelectedDate(dates.start)}
              placeholder="Select a date"
            />
          </InputGroup>

          <InputGroup>
            <label>Guests</label>
            <GuestSelector
              value={guests}
              onChange={setGuests}
              min={1}
              max={10}
              label="Guests"
            />
          </InputGroup>
        </StickySidebar>
      }
      reviews={<ReviewsSection />}
    >
      <Section>
        <h2>About This Experience</h2>
        {(exp.longDescription || exp.description || '').split('\n\n').map((p, i) => (
          <p key={i}>{p}</p>
        ))}
      </Section>

      {exp.includes && (
        <Section>
          <h2>What's Included</h2>
          <IncludesList>
            {exp.includes.map((item, i) => (
              <li key={i}>{item}</li>
            ))}
          </IncludesList>
        </Section>
      )}

      <Section>
        <h2>Experience Details</h2>
        <p><strong>Meeting Point:</strong> {exp.meetingPoint || 'Provided upon booking'}</p>
        <p style={{ marginTop: '0.5rem' }}><strong>Best Season:</strong> {exp.bestSeason || 'Year round'}</p>
      </Section>

      <Section>
        <h2>Where to Stay</h2>
        <p style={{ marginBottom: '1.25rem' }}>Hand-picked sanctuaries near this experience.</p>
        <div style={{ display: 'grid', gap: '1rem' }}>
          {accommodations.slice(0, 3).map(a => (
            <RelatedCard key={a.id} to={`/stays/${a.slug}`}>
              <img src={a.images[0]} alt={a.name} loading="lazy" />
              <div>
                <div className="title">{a.name}</div>
                <div className="sub">{a.location} &middot; From ${a.priceFrom}/night</div>
              </div>
            </RelatedCard>
          ))}
        </div>
      </Section>

      <Section>
        <h2>Dine Nearby</h2>
        <div style={{ display: 'grid', gap: '1rem' }}>
          {restaurants.slice(0, 2).map(r => (
            <RelatedCard key={r.id} to={`/dining/${r.slug}`}>
              <img src={r.images[0]} alt={r.name} loading="lazy" />
              <div>
                <div className="title">{r.name}</div>
                <div className="sub">{r.cuisine} &middot; {r.priceRange}</div>
              </div>
            </RelatedCard>
          ))}
        </div>
      </Section>
    </EditorialDetailLayout>
  );
}
