import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import styled from 'styled-components';
import { motion } from 'framer-motion';

/* ─── Hero Gallery ─── */
const HeroGalleryWrapper = styled.section`
  position: relative;
  height: ${p => p.$height || '65vh'};
  min-height: ${p => p.$minHeight || '450px'};
  overflow: hidden;
  background: ${p => p.theme.colors.primaryDark};

  @media (max-width: ${p => p.theme.breakpoints.tablet}) {
    height: ${p => p.$mobileHeight || '50vh'};
    min-height: ${p => p.$mobileMinHeight || '350px'};
  }
`;

const GallerySlide = styled.div`
  position: absolute;
  inset: 0;

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  &::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(
      180deg,
      rgba(10, 33, 26, 0.12) 0%,
      transparent 30%,
      rgba(10, 33, 26, 0.45) 100%
    );
    pointer-events: none;
  }
`;

const BackBtn = styled(Link)`
  position: absolute;
  top: 1.5rem;
  left: 1.5rem;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  padding: 0.55rem 1.2rem;
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.sm};
  font-weight: 500;
  color: ${p => p.theme.colors.text};
  text-decoration: none;
  transition: all ${p => p.theme.transitions.fast};
  border-radius: ${p => p.theme.borderRadius.lg};

  &:hover {
    background: white;
    transform: translateY(-1px);
  }
`;

const Thumbs = styled.div`
  position: absolute;
  bottom: 1.5rem;
  left: 1.5rem;
  display: flex;
  gap: 0.5rem;
  z-index: 3;

  @media (max-width: ${p => p.theme.breakpoints.mobile}) {
    display: none;
  }
`;

const Thumb = styled.button`
  width: 72px;
  height: 52px;
  overflow: hidden;
  border: 2px solid ${p => (p.$active ? 'rgba(255,255,255,0.95)' : 'transparent')};
  opacity: ${p => (p.$active ? 1 : 0.65)};
  cursor: pointer;
  padding: 0;
  transition: all ${p => p.theme.transitions.fast};
  background: none;
  flex-shrink: 0;

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  &:hover {
    opacity: 1;
  }
`;

const NavBtns = styled.div`
  position: absolute;
  bottom: 1.5rem;
  right: 1.5rem;
  display: flex;
  gap: 0.5rem;
  z-index: 3;
`;

const NavBtn = styled.button`
  width: 44px;
  height: 44px;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all ${p => p.theme.transitions.fast};
  border: none;
  border-radius: ${p => p.theme.borderRadius.lg};
  color: ${p => p.theme.colors.text};

  &:hover {
    background: white;
    transform: translateY(-1px);
  }
`;

const ImageCount = styled.div`
  position: absolute;
  bottom: 1.5rem;
  right: 8rem;
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(12px);
  padding: 0.35rem 0.85rem;
  border-radius: ${p => p.theme.borderRadius.lg};
  font-family: ${p => p.theme.fonts.sans};
  font-size: 11px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.85);
  z-index: 3;

  @media (max-width: ${p => p.theme.breakpoints.mobile}) {
    display: none;
  }
`;

export function HeroGallery({
  images = [],
  backTo = '/discover',
  backLabel = 'Back',
  height,
  minHeight,
  mobileHeight,
  mobileMinHeight,
  alt = 'Gallery image',
}) {
  const [idx, setIdx] = useState(0);
  const count = images.length;

  if (count === 0) return null;

  return (
    <HeroGalleryWrapper
      $height={height}
      $minHeight={minHeight}
      $mobileHeight={mobileHeight}
      $mobileMinHeight={mobileMinHeight}
    >
      <BackBtn to={backTo}>&larr; {backLabel}</BackBtn>

      <GallerySlide>
        <motion.img
          key={idx}
          src={images[idx]}
          alt={alt}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5 }}
        />
      </GallerySlide>

      {count > 1 && (
        <>
          <Thumbs>
            {images.map((img, i) => (
              <Thumb key={i} $active={i === idx} onClick={() => setIdx(i)}>
                <img src={img} alt="" loading="lazy" />
              </Thumb>
            ))}
          </Thumbs>
          <ImageCount>{idx + 1} / {count}</ImageCount>
          <NavBtns>
            <NavBtn onClick={() => setIdx((idx - 1 + count) % count)} aria-label="Previous image">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M15 18l-6-6 6-6" />
              </svg>
            </NavBtn>
            <NavBtn onClick={() => setIdx((idx + 1) % count)} aria-label="Next image">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M9 18l6-6-6-6" />
              </svg>
            </NavBtn>
          </NavBtns>
        </>
      )}
    </HeroGalleryWrapper>
  );
}

/* ─── Image Grid ─── */
const GridWrapper = styled.div`
  display: grid;
  grid-template-columns: ${p => p.$columns || 'repeat(3, 1fr)'};
  gap: ${p => p.$gap || '0.5rem'};
  border-radius: ${p => p.$rounded ? p.theme.borderRadius.xl : '0'};
  overflow: hidden;

  @media (max-width: ${p => p.theme.breakpoints.tablet}) {
    grid-template-columns: 1fr;
  }
`;

const GridImage = styled.div`
  position: relative;
  aspect-ratio: ${p => p.$aspect || '16/10'};
  overflow: hidden;
  cursor: pointer;

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  }

  &:hover img {
    transform: scale(1.04);
  }
`;

const GridOverlay = styled.div`
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(10, 33, 26, 0.5) 100%);
  pointer-events: none;
`;

const GridLabel = styled.div`
  position: absolute;
  bottom: 1rem;
  left: 1rem;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.9);
`;

const CountOverlay = styled.div`
  position: absolute;
  inset: 0;
  background: rgba(10, 33, 26, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 1.25rem;
  font-weight: 300;
  color: white;
  letter-spacing: 0.1em;
`;

export function ImageGrid({ images = [], columns, gap, rounded, labels }) {
  const display = images.slice(0, 4);
  const remaining = images.length - 3;

  if (display.length === 0) return null;

  return (
    <GridWrapper $columns={columns} $gap={gap} $rounded={rounded}>
      {display.map((img, i) => {
        const isLast = i === 3 && remaining > 0;
        return (
          <GridImage key={i} $aspect={i === 0 ? '16/10' : '4/3'}>
            <img src={img} alt={(labels && labels[i]) || `Gallery ${i + 1}`} loading="lazy" />
            {i === 0 && display.length > 1 && <GridOverlay />}
            {labels && labels[i] && <GridLabel>{labels[i]}</GridLabel>}
            {isLast && <CountOverlay>+{remaining}</CountOverlay>}
          </GridImage>
        );
      })}
    </GridWrapper>
  );
}

const Galleries = { HeroGallery, ImageGrid };
export default Galleries;
