import React, { useState, useRef, useEffect } from 'react';
import styled from 'styled-components';
import { motion, AnimatePresence } from 'framer-motion';

const PickerWrapper = styled.div`
  position: relative;
`;

const PickerTrigger = styled.button`
  width: 100%;
  padding: 0.85rem 1rem;
  border: 1px solid ${p => p.$hasValue ? p.theme.colors.primary : p.theme.colors.border};
  border-radius: ${p => p.theme.borderRadius.lg};
  background: ${p => p.theme.colors.background};
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.md};
  color: ${p => p.$hasValue ? p.theme.colors.text : p.theme.colors.textMuted};
  cursor: pointer;
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  transition: all 0.3s ease;

  &:hover {
    border-color: ${p => p.theme.colors.primaryLight};
  }

  &:focus {
    outline: none;
    border-color: ${p => p.theme.colors.primary};
  }
`;

const Chevron = styled.span`
  color: ${p => p.theme.colors.textMuted};
  transition: transform 0.3s ease;
  transform: rotate(${p => p.$open ? '180deg' : '0deg'});
  font-size: 10px;
`;

const Dropdown = styled(motion.div)`
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  background: ${p => p.theme.colors.white};
  border: 1px solid ${p => p.theme.colors.border};
  border-radius: ${p => p.theme.borderRadius.xl};
  box-shadow: 0 12px 40px rgba(10, 33, 26, 0.12);
  z-index: 50;
  padding: 1.25rem;
`;

const MonthNav = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
`;

const MonthLabel = styled.span`
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.sm};
  font-weight: 600;
  color: ${p => p.theme.colors.text};
  letter-spacing: 0.04em;
`;

const NavArrow = styled.button`
  background: none;
  border: 1px solid ${p => p.theme.colors.border};
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: ${p => p.theme.colors.textLight};
  transition: all 0.2s ease;

  &:hover {
    border-color: ${p => p.theme.colors.primary};
    color: ${p => p.theme.colors.primary};
  }
`;

const WeekDays = styled.div`
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
  margin-bottom: 4px;
`;

const WeekDay = styled.span`
  font-family: ${p => p.theme.fonts.sans};
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: ${p => p.theme.colors.textMuted};
  text-align: center;
  padding: 0.35rem 0;
`;

const DaysGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
`;

const DayButton = styled.button`
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 13px;
  font-weight: ${p => p.$selected ? 600 : 400};
  color: ${p => {
    if (p.$disabled) return p.theme.colors.border;
    if (p.$selected) return p.theme.colors.white;
    if (p.$inRange) return p.theme.colors.text;
    return p.theme.colors.textLight;
  }};
  background: ${p => {
    if (p.$selected) return p.theme.colors.primaryDark;
    if (p.$inRange) return p.theme.colors.backgroundAlt;
    return 'transparent';
  }};
  border: none;
  border-radius: 50%;
  cursor: ${p => p.$disabled ? 'default' : 'pointer'};
  transition: all 0.2s ease;
  position: relative;

  ${p => p.$isToday && !p.$selected && `
    &::after {
      content: '';
      position: absolute;
      bottom: 4px;
      width: 4px;
      height: 4px;
      border-radius: 50%;
      background: ${p.theme.colors.champagne};
    }
  `}

  &:hover:not(:disabled) {
    background: ${p => p.$selected ? p.theme.colors.primary : p.theme.colors.backgroundAlt};
  }
`;

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const DAYS = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];

function getDaysInMonth(year, month) {
  return new Date(year, month + 1, 0).getDate();
}

function getFirstDayOfMonth(year, month) {
  return new Date(year, month, 1).getDay();
}

export default function DateRangePicker({ startDate, endDate, onChange, placeholder = 'Select dates' }) {
  const [open, setOpen] = useState(false);
  const [viewDate, setViewDate] = useState(new Date());
  const [selecting, setSelecting] = useState('start');
  const wrapperRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (wrapperRef.current && !wrapperRef.current.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const handleDayClick = (day) => {
    const clicked = new Date(year, month, day);
    clicked.setHours(0, 0, 0, 0);

    if (selecting === 'start') {
      onChange({ start: clicked, end: null });
      setSelecting('end');
    } else {
      if (clicked < startDate) {
        onChange({ start: clicked, end: null });
        setSelecting('end');
      } else {
        onChange({ start: startDate, end: clicked });
        setSelecting('start');
        setOpen(false);
      }
    }
  };

  const isDisabled = (day) => {
    const d = new Date(year, month, day);
    d.setHours(0, 0, 0, 0);
    return d < today;
  };

  const isSelected = (day) => {
    const d = new Date(year, month, day);
    d.setHours(0, 0, 0, 0);
    return (startDate && d.getTime() === startDate.getTime()) || (endDate && d.getTime() === endDate.getTime());
  };

  const isInRange = (day) => {
    if (!startDate || !endDate) return false;
    const d = new Date(year, month, day);
    d.setHours(0, 0, 0, 0);
    return d > startDate && d < endDate;
  };

  const isToday = (day) => {
    const d = new Date(year, month, day);
    return d.getTime() === today.getTime();
  };

  const formatDisplay = (date) => {
    if (!date) return '';
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  };

  const displayValue = startDate
    ? `${formatDisplay(startDate)}${endDate ? ` — ${formatDisplay(endDate)}` : selecting === 'end' ? ' — ...' : ''}`
    : '';

  return (
    <PickerWrapper ref={wrapperRef}>
      <PickerTrigger
        onClick={() => setOpen(!open)}
        $hasValue={!!startDate}
        type="button"
      >
        <span>{displayValue || placeholder}</span>
        <Chevron $open={open}>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
        </Chevron>
      </PickerTrigger>

      <AnimatePresence>
        {open && (
          <Dropdown
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            transition={{ duration: 0.2 }}
          >
            <MonthNav>
              <NavArrow onClick={() => setViewDate(new Date(year, month - 1))} aria-label="Previous month">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
              </NavArrow>
              <MonthLabel>{MONTHS[month]} {year}</MonthLabel>
              <NavArrow onClick={() => setViewDate(new Date(year, month + 1))} aria-label="Next month">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
              </NavArrow>
            </MonthNav>

            <WeekDays>
              {DAYS.map(d => <WeekDay key={d}>{d}</WeekDay>)}
            </WeekDays>

            <DaysGrid>
              {Array.from({ length: firstDay }, (_, i) => (
                <div key={`empty-${i}`} />
              ))}
              {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(day => (
                <DayButton
                  key={day}
                  $selected={isSelected(day)}
                  $inRange={isInRange(day)}
                  $disabled={isDisabled(day)}
                  $isToday={isToday(day)}
                  onClick={() => !isDisabled(day) && handleDayClick(day)}
                  disabled={isDisabled(day)}
                  type="button"
                >
                  {day}
                </DayButton>
              ))}
            </DaysGrid>
          </Dropdown>
        )}
      </AnimatePresence>
    </PickerWrapper>
  );
}
