const CATEGORIES = ['All', 'Heritage Hotel', 'Safari Lodge', 'Boutique Hotel', 'Resort', 'Guest Lodge', 'Hotel', 'Eco Lodge'];

const SKELETON_COUNT = 6;

export default function StaysPage({ isInCollection, toggleCollection }) {
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('All');
  const [sort, setSort] = useState('recommended');
  const [isLoading] = useState(false);
  const [filterDrawerOpen, setFilterDrawerOpen] = useState(false);

  const filtered = useMemo(() => {
    let results = accommodations;

    if (search) {
      const q = search.toLowerCase();
      results = results.filter(a =>
        a.name.toLowerCase().includes(q) ||
        a.location.toLowerCase().includes(q) ||
        a.category.toLowerCase().includes(q) ||
        a.tagline.toLowerCase().includes(q)
      );
    }

    if (category !== 'All') results = results.filter(a => a.category === category);

    switch (sort) {
      case 'rating': results = [...results].sort((a, b) => b.rating - a.rating); break;
      case 'price-low': results = [...results].sort((a, b) => a.priceFrom - b.priceFrom); break;
      case 'price-high': results = [...results].sort((a, b) => b.priceFrom - a.priceFrom); break;
      case 'reviews': results = [...results].sort((a, b) => b.reviewCount - a.reviewCount); break;
      default: break;
    }

    return results;
  }, [search, category, sort]);

  const handleToggleSave = (acc) => {
    toggleCollection({
      id: acc.id,
      type: 'accommodation',
      name: acc.name,
      image: acc.images[0],
      price: acc.priceFrom,
      location: acc.location
    });
  };

  return (
    <PageWrapper>
      <PageHero
        cssBackground="https://www.shearwatervictoriafalls.com/wp-content/uploads/2024/04/Heli-6-scaled-1.jpg"
        eyebrow="Curated Collection"
        title="Where to Stay"
        subtitle="From heritage grandeur to intimate bush camps — handpicked sanctuaries for the discerning traveller"
      >
        <SearchWrapper>
          <SearchBar>
            <SearchIcon>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="11" cy="11" r="8" />
                <path d="M21 21l-4.35-4.35" />
              </svg>
            </SearchIcon>
            <SearchInput
              type="text"
              placeholder="Search by name, location, or style..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              aria-label="Search stays"
            />
            <SearchCount>{filtered.length}</SearchCount>
          </SearchBar>
        </SearchWrapper>
      </PageHero>

      <ContentSection>
        <Container $large>
          <ToolbarRow>
            <FilterPills>
              {CATEGORIES.map(cat => (
                <FilterPill
                  key={cat}
                  $active={category === cat}
                  onClick={() => setCategory(cat)}
                >
                  {cat}
                </FilterPill>
              ))}
            </FilterPills>
            <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center' }}>
              <MobileFilterBtn onClick={() => setFilterDrawerOpen(true)}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                  <line x1="4" y1="6" x2="20" y2="6" />
                  <line x1="8" y1="12" x2="20" y2="12" />
                  <line x1="12" y1="18" x2="20" y2="18" />
                </svg>
                Filters
              </MobileFilterBtn>
              <SortDropdown value={sort} onChange={e => setSort(e.target.value)}>
                <option value="recommended">Recommended</option>
                <option value="rating">Highest Rated</option>
                <option value="price-low">Price: Low to High</option>
                <option value="price-high">Price: High to Low</option>
                <option value="reviews">Most Reviewed</option>
              </SortDropdown>
            </div>
          </ToolbarRow>

          <ResultsLabel>
            Showing <strong>{filtered.length}</strong> {filtered.length === 1 ? 'property' : 'properties'}
          </ResultsLabel>

          {isLoading ? (
            <EditorialGrid>
              <SkeletonCard count={SKELETON_COUNT} />
            </EditorialGrid>
          ) : filtered.length === 0 ? (
            <EmptyState
              initial="hidden"
              animate="visible"
              variants={fadeIn}
            >
              <h3>No properties found</h3>
              <p>Try adjusting your search or explore a different category</p>
            </EmptyState>
          ) : (
            <motion.div initial="hidden" animate="visible" variants={stagger}>
              <EditorialGrid>
                {filtered.map((acc, idx) => (
                  <ListingCard
                    key={acc.id}
                    to={`/stays/${acc.slug}`}
                    image={acc.images[0]}
                    name={acc.name}
                    location={acc.location}
                    description={acc.tagline || acc.description}
                    category={acc.category}
                    rating={acc.rating}
                    price={acc.priceFrom}
                    priceLabel="/ night"
                    aspect={idx % 3 === 0 ? '4/3' : '16/10'}
                    isSaved={isInCollection(acc.id)}
                    onToggleSave={() => handleToggleSave(acc)}
                    animationVariants={fadeUp}
                  />
                ))}
              </EditorialGrid>
            </motion.div>
          )}
        </Container>
      </ContentSection>

      <FilterDrawer
        open={filterDrawerOpen}
        onClose={() => setFilterDrawerOpen(false)}
        title="Filter Stays"
        categories={CATEGORIES}
        activeCategory={category}
        onCategoryChange={(cat) => {
          setCategory(cat);
          setFilterDrawerOpen(false);
        }}
      />
    </PageWrapper>
  );
}
