import React from 'react';
import styled from 'styled-components';
import { motion } from 'framer-motion';

const HeroWrapper = styled.section`
  position: relative;
  height: ${p => p.$height || '72vh'};
  min-height: ${p => p.$minHeight || '520px'};
  max-height: ${p => p.$maxHeight || '700px'};
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: ${p => p.theme.colors.primaryDark};

  &::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(
      180deg,
      rgba(10, 33, 26, 0.35) 0%,
      rgba(10, 33, 26, 0.45) 50%,
      rgba(10, 33, 26, 0.78) 100%
    );
    z-index: 1;
  }
`;

const HeroBgImage = styled.div`
  position: absolute;
  inset: 0;
  z-index: 0;

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  &::after {
    content: '';
    position: absolute;
    inset: 0;
    background: ${p =>
      p.$overlay ||
      'linear-gradient(180deg, rgba(10,33,26,0.15) 0%, rgba(10,33,26,0.05) 40%, rgba(10,33,26,0.55) 100%)'
    };
  }
`;

const HeroBgCSS = styled.div`
  position: absolute;
  inset: 0;
  z-index: 0;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
      ${p => p.$gradient ||
        'linear-gradient(180deg, rgba(10,33,26,0.35) 0%, rgba(10,33,26,0.55) 50%, rgba(10,33,26,0.78) 100%)'
      },
      url('${p => p.$image}') center/cover no-repeat;
  }
`;

const HeroContent = styled.div`
  position: relative;
  z-index: 2;
  max-width: ${p => p.$contentMaxWidth || '720px'};
  margin: 0 auto;
  padding: 0 2rem;
  width: 100%;
`;

const Eyebrow = styled(motion.div)`
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: ${p => p.$light ? p.theme.colors.champagneLight : p.theme.colors.champagne};
  margin-bottom: 1.5rem;

  &::before, &::after {
    content: '';
    width: 28px;
    height: 1px;
    background: ${p => p.theme.colors.champagne};
    opacity: 0.5;
  }
`;

const Title = styled(motion.h1)`
  font-family: ${p => p.theme.fonts.serif};
  font-size: clamp(2.6rem, 5.5vw, 4.4rem);
  font-weight: 300;
  color: ${p => p.theme.colors.white};
  line-height: 1.1;
  letter-spacing: -0.025em;
  margin-bottom: 1.25rem;
`;

const Subtitle = styled(motion.p)`
  font-family: ${p => p.theme.fonts.sans};
  font-size: ${p => p.theme.fontSizes.md};
  font-weight: 300;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.85;
  max-width: 540px;
  margin: 0 auto 2rem;
`;

const Tagline = styled(motion.p)`
  font-family: ${p => p.theme.fonts.serif};
  font-size: ${p => p.theme.fontSizes.lg};
  font-style: italic;
  color: rgba(255, 255, 255, 0.5);
  margin-top: 1.5rem;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.7;
`;

const ChildrenWrap = styled(motion.div)`
  margin-top: 0.5rem;
`;

const fadeUp = {
  hidden: { opacity: 0, y: 20 },
  visible: (i) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.8, delay: i * 0.12, ease: [0.22, 1, 0.36, 1] },
  }),
};

export default function PageHero({
  image,
  cssBackground,
  height,
  minHeight,
  maxHeight,
  gradient,
  contentMaxWidth,
  eyebrow,
  title,
  subtitle,
  tagline,
  children,
}) {
  return (
    <HeroWrapper $height={height} $minHeight={minHeight} $maxHeight={maxHeight}>
      {image && (
        <HeroBgImage>
          <img src={image} alt="" />
        </HeroBgImage>
      )}
      {cssBackground && (
        <HeroBgCSS $image={cssBackground} $gradient={gradient} />
      )}

      <HeroContent $contentMaxWidth={contentMaxWidth}>
        {eyebrow && (
          <Eyebrow custom={0} variants={fadeUp} initial="hidden" animate="visible">
            {eyebrow}
          </Eyebrow>
        )}
        {title && (
          <Title custom={1} variants={fadeUp} initial="hidden" animate="visible">
            {title}
          </Title>
        )}
        {subtitle && (
          <Subtitle custom={2} variants={fadeUp} initial="hidden" animate="visible">
            {subtitle}
          </Subtitle>
        )}
        {tagline && (
          <Tagline custom={3} variants={fadeUp} initial="hidden" animate="visible">
            {tagline}
          </Tagline>
        )}
        {children && (
          <ChildrenWrap custom={children ? 3 : 2} variants={fadeUp} initial="hidden" animate="visible">
            {children}
          </ChildrenWrap>
        )}
      </HeroContent>
    </HeroWrapper>
  );
}
