import React from 'react';
import styled from 'styled-components';

const Label = styled.div`
  font-family: ${p => p.theme.fonts.sans};
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: ${p => p.$light ? 'rgba(255, 255, 255, 0.6)' : p.theme.colors.cocoa};
  margin-bottom: ${p => p.$mb || '1rem'};
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;

  &::before {
    content: '';
    width: 28px;
    height: 1px;
    background: ${p => p.$light ? 'rgba(255, 255, 255, 0.3)' : p.theme.colors.champagne};
  }
`;

export default function SectionLabel({ children, light = false, marginBottom, ...props }) {
  return (
    <Label $light={light} $mb={marginBottom} {...props}>
      {children}
    </Label>
  );
}
