import React from 'react';
import styled from 'styled-components';
import { motion, AnimatePresence } from 'framer-motion';

const Overlay = styled(motion.div)`
  position: fixed;
  inset: 0;
  background: rgba(10, 33, 26, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 2000;
`;

const Drawer = styled(motion.div)`
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: ${p => p.theme.colors.white};
  border-radius: ${p => p.theme.borderRadius.xl} ${p => p.theme.borderRadius.xl} 0 0;
  box-shadow: 0 -8px 40px rgba(10, 33, 26, 0.15);
  z-index: 2001;
  max-height: 80vh;
  overflow-y: auto;
  padding: 1.5rem;
`;

const Handle = styled.div`
  width: 40px;
  height: 4px;
  border-radius: 2px;
  background: ${p => p.theme.colors.border};
  margin: 0 auto 1.25rem;
`;

const Header = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
`;

const Title = styled.h3`
  font-family: ${p => p.theme.fonts.serif};
  font-size: ${p => p.theme.fontSizes.xl};
  font-weight: 400;
  color: ${p => p.theme.colors.primaryDark};
`;

const CloseBtn = styled.button`
  background: none;
  border: none;
  font-size: 1.25rem;
  color: ${p => p.theme.colors.textMuted};
  cursor: pointer;
  padding: 0.25rem;
  transition: color 0.2s ease;

  &:hover {
    color: ${p => p.theme.colors.text};
  }
`;

const FilterGroup = styled.div`
  margin-bottom: 1.5rem;
`;

const FilterLabel = styled.div`
  font-family: ${p => p.theme.fonts.sans};
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: ${p => p.theme.colors.textMuted};
  margin-bottom: 0.75rem;
`;

const PillsWrap = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
`;

const Pill = styled.button`
  padding: 0.55rem 1.1rem;
  background: ${p => p.$active ? p.theme.colors.primaryDark : 'transparent'};
  color: ${p => p.$active ? p.theme.colors.white : p.theme.colors.textLight};
  border: 1px solid ${p => p.$active ? p.theme.colors.primaryDark : p.theme.colors.border};
  border-radius: 999px;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: all 0.3s ease;

  &:hover {
    border-color: ${p => p.$active ? p.theme.colors.primaryDark : p.theme.colors.primaryLight};
  }
`;

const ApplyBtn = styled.button`
  width: 100%;
  padding: 1rem;
  background: ${p => p.theme.colors.primaryDark};
  color: ${p => p.theme.colors.white};
  border: none;
  border-radius: 999px;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  margin-top: 0.5rem;

  &:hover {
    background: ${p => p.theme.colors.primary};
    transform: translateY(-1px);
  }
`;

const MobileFilterBtn = styled.button`
  display: none;
  align-items: center;
  gap: 0.5rem;
  padding: 0.55rem 1.1rem;
  background: ${p => p.theme.colors.white};
  border: 1px solid ${p => p.theme.colors.border};
  border-radius: 999px;
  font-family: ${p => p.theme.fonts.sans};
  font-size: 12px;
  font-weight: 500;
  color: ${p => p.theme.colors.text};
  cursor: pointer;
  transition: all 0.3s ease;

  svg {
    width: 14px;
    height: 14px;
  }

  @media (max-width: ${p => p.theme.breakpoints.tablet}) {
    display: inline-flex;
  }
`;

export { MobileFilterBtn };

export default function FilterDrawer({ open, onClose, title = 'Filters', categories, activeCategory, onCategoryChange, children }) {
  return (
    <AnimatePresence>
      {open && (
        <>
          <Overlay
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
          />
          <Drawer
            initial={{ y: '100%' }}
            animate={{ y: 0 }}
            exit={{ y: '100%' }}
            transition={{ type: 'spring', damping: 30, stiffness: 300 }}
          >
            <Handle />
            <Header>
              <Title>{title}</Title>
              <CloseBtn onClick={onClose} aria-label="Close filters">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round">
                  <path d="M18 6L6 18M6 6l12 12" />
                </svg>
              </CloseBtn>
            </Header>

            {categories && (
              <FilterGroup>
                <FilterLabel>Category</FilterLabel>
                <PillsWrap>
                  {categories.map(cat => (
                    <Pill
                      key={cat}
                      $active={activeCategory === cat}
                      onClick={() => onCategoryChange(cat)}
                    >
                      {cat}
                    </Pill>
                  ))}
                </PillsWrap>
              </FilterGroup>
            )}

            {children}

            <ApplyBtn onClick={onClose}>Apply Filters</ApplyBtn>
          </Drawer>
        </>
      )}
    </AnimatePresence>
  );
}
