export default function ZambeziMap() {
  const [activeCategory, setActiveCategory] = useState('All');
  const [selectedPoint, setSelectedPoint] = useState(MAP_POINTS[0]);

  const filteredPoints = activeCategory === 'All'
    ? MAP_POINTS
    : MAP_POINTS.filter(p => p.category === activeCategory);

  return (
    <MapContainer>
      <MapHeader>
        <HeaderText>
          <Subtitle $light>Spatial Interactive Gateway</Subtitle>
          <HeadingH $light>Dual-Nation Zambezi Ecosystem</HeadingH>
        </HeaderText>

        <FilterGroup>
          {['All', 'Stays', 'Experiences', 'Dining', 'Border Points'].map(cat => (
            <FilterBtn
              key={cat}
              $active={activeCategory === cat}
              onClick={() => setActiveCategory(cat)}
            >
              {cat}
            </FilterBtn>
          ))}
        </FilterGroup>
      </MapHeader>

      <MapCanvas>
        {/* Vector Background Curved River Map representation */}
        <MapSvgWrapper viewBox="0 0 1000 600" preserveAspectRatio="none">
          {/* Zambezi River Curve */}
          <path
            d="M 0,220 Q 300,180 480,320 T 750,280 T 1000,450"
            fill="none"
            stroke="#215B49"
            strokeWidth="60"
            strokeLinecap="round"
          />
          <path
            d="M 0,220 Q 300,180 480,320 T 750,280 T 1000,450"
            fill="none"
            stroke="#163D31"
            strokeWidth="30"
            strokeLinecap="round"
          />

          {/* Batoka Gorge Line */}
          <path
            d="M 520,340 C 560,420 540,520 620,600"
            fill="none"
            stroke="#C5A470"
            strokeWidth="3"
            strokeDasharray="6,6"
            opacity="0.4"
          />

          {/* Victoria Falls Spray Point */}
          <circle cx="500" cy="330" r="45" fill="rgba(255,255,255,0.06)" />
          <circle cx="500" cy="330" r="25" fill="rgba(255,255,255,0.12)" />
        </MapSvgWrapper>

        {/* Spatial Labels */}
        <MapLabel $x={30} $y={25} $light>ZIMBABWE (VICTORIA FALLS TOWN)</MapLabel>
        <MapLabel $x={75} $y={20} $light>ZAMBIA (LIVINGSTONE)</MapLabel>
        <MapLabel $x={50} $y={31}>MOSI-OA-TUNYA SPRAY ZONE</MapLabel>

        {/* Interactive Map Pins */}
        {filteredPoints.map(point => {
          const isSelected = selectedPoint?.id === point.id;
          return (
            <MapPin
              key={point.id}
              $x={point.x}
              $y={point.y}
              $selected={isSelected}
              onClick={() => setSelectedPoint(point)}
              aria-label={point.name}
            >
              {isSelected && <span className="pulse-ring" />}
              <Icon name={point.icon} size={15} />
            </MapPin>
          );
        })}

        {/* Floating Tooltip Card */}
        <AnimatePresence mode="wait">
          {selectedPoint && (
            <TooltipCard
              key={selectedPoint.id}
              initial={{ opacity: 0, y: 15 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 15 }}
              transition={{ duration: 0.3 }}
            >
              <div className="img-wrap">
                <img src={selectedPoint.image} alt={selectedPoint.name} loading="lazy" />
              </div>
              <div className="country">{selectedPoint.country}</div>
              <div className="title">{selectedPoint.name}</div>
              <div className="meta">{selectedPoint.meta}</div>
              <Link to={selectedPoint.link} className="card-btn">
                Explore Destination &rarr;
              </Link>
            </TooltipCard>
          )}
        </AnimatePresence>
      </MapCanvas>
    </MapContainer>
  );
}
