const QUICK_ACTIONS = [
  { label: 'Plan my trip', message: 'I\'d like help planning my Victoria Falls journey.' },
  { label: 'Best time to visit', message: 'When is the best time to visit Victoria Falls?' },
  { label: 'Where should I stay?', message: 'Can you recommend where to stay?' },
  { label: 'Airport transfer', message: 'I need an airport transfer. What are my options?' },
];

function generateAIResponse(msg) {
  const lower = msg.toLowerCase();

  if (lower.includes('plan') || lower.includes('trip') || lower.includes('itinerary')) {
    return {
      text: 'I\'d love to help you plan your Victoria Falls trip! Here\'s a suggested itinerary:',
      cards: [
        { type: 'experience', item: experiences.find(e => e.slug === 'sunset-cruise') },
        { type: 'experience', item: experiences.find(e => e.slug === 'helicopter-flight') },
        { type: 'experience', item: experiences.find(e => e.slug === 'white-water-rafting') },
      ].filter(c => c.item)
    };
  }

  if (lower.includes('best time') || lower.includes('when') || lower.includes('season')) {
    return {
      text: 'Victoria Falls is year-round, but the best balance is May-August — spectacular falls and ideal weather. Here are some experiences perfect for each season:',
      cards: [
        { type: 'experience', item: experiences.find(e => e.slug === 'sunset-cruise') },
        { type: 'experience', item: experiences.find(e => e.slug === 'guided-falls-tour') },
      ].filter(c => c.item)
    };
  }

  if (lower.includes('stay') || lower.includes('hotel') || lower.includes('lodge')) {
    return {
      text: 'Great options depending on your style. Here are my top recommendations:',
      cards: [
        { type: 'accommodation', item: accommodations.find(a => a.slug === 'victoria-falls-hotel') },
        { type: 'accommodation', item: accommodations.find(a => a.slug === 'victoria-falls-safari-lodge') },
        { type: 'accommodation', item: accommodations.find(a => a.slug === 'ananatara-stanley-livingstone') },
      ].filter(c => c.item)
    };
  }

  if (lower.includes('transport') || lower.includes('transfer') || lower.includes('airport')) {
    return {
      text: 'Transport options for your Victoria Falls journey:',
      cards: [
        { type: 'transport', label: 'Airport Transfer', desc: '$35 per vehicle, ~20 min ride', link: '/transport' },
        { type: 'transport', label: 'Private Driver', desc: '$50/hr for full-day exploration', link: '/transport' },
      ]
    };
  }

  if (lower.includes('dinner') || lower.includes('dining') || lower.includes('restaurant') || lower.includes('food')) {
    return {
      text: 'Victoria Falls has incredible dining. Here are my top picks:',
      cards: [
        { type: 'restaurant', item: restaurants.find(r => r.slug === 'the-boma') },
        { type: 'restaurant', item: restaurants.find(r => r.slug === 'djuma-grill-room') },
      ].filter(c => c.item)
    };
  }

  if (lower.includes('adventure') || lower.includes('exciting') || lower.includes('thrill')) {
    return {
      text: 'For the adventurous soul, these experiences will get your heart racing:',
      cards: [
        { type: 'experience', item: experiences.find(e => e.slug === 'white-water-rafting') },
        { type: 'experience', item: experiences.find(e => e.slug === 'bungee-jumping') },
      ].filter(c => c.item)
    };
  }

  return `Thank you for your inquiry. I can assist with:\n\n• Curating personalized itineraries\n• Handpicked accommodation selection\n• Flight of Angels & Helicopter tours\n• Zambezi River cruises & dining\n\nHow may I assist your Victoria Falls journey today?`;
}

export default function FloatingConcierge() {
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState([
    { from: 'bot', text: 'Welcome to VicFalls One. I\'m your Digital Butler for Victoria Falls. How may I curate your journey today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEnd = useRef(null);

  useEffect(() => {
    messagesEnd.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const send = (text) => {
    const msg = text || input.trim();
    if (!msg) return;
    setMessages(prev => [...prev, { from: 'user', text: msg }]);
    setInput('');
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        from: 'bot',
        text: generateAIResponse(msg)
      }]);
    }, 1200);
  };

  return (
    <>
      <AnimatePresence>
        {open && (
          <Panel
            initial={{ opacity: 0, y: 20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.95 }}
            transition={{ duration: 0.25 }}
          >
            <PanelHeader>
              <PanelTitle>Digital Butler</PanelTitle>
              <CloseButton onClick={() => setOpen(false)} aria-label="Close concierge">&times;</CloseButton>
            </PanelHeader>
            <Messages>
              {messages.map((m, i) => (
                <React.Fragment key={i}>
                  <Bubble $user={m.from === 'user'}>
                    {typeof m.text === 'string' ? m.text : ''}
                  </Bubble>
                  {m.cards && m.cards.length > 0 && (
                    <RichCards>
                      {m.cards.map((card, ci) => {
                        if (card.type === 'transport') {
                          return (
                            <RichCard key={ci} to={card.link}>
                              <RichCardBody>
                                <RichCardName>{card.label}</RichCardName>
                                <RichCardMeta>{card.desc}</RichCardMeta>
                              </RichCardBody>
                            </RichCard>
                          );
                        }
                        const item = card.item;
                        if (!item) return null;
                        const link = card.type === 'accommodation' ? `/stays/${item.slug}`
                          : card.type === 'restaurant' ? `/dining/${item.slug}`
                          : `/experiences/${item.slug}`;
                        return (
                          <RichCard key={ci} to={link}>
                            <RichCardImg>
                              <img src={item.images?.[0] || item.image} alt={item.name} />
                            </RichCardImg>
                            <RichCardBody>
                              <RichCardName>{item.name}</RichCardName>
                              <RichCardMeta>{item.location || item.cuisine || item.category}</RichCardMeta>
                              {item.priceFrom && <RichCardPrice>From ${item.priceFrom}/night</RichCardPrice>}
                              {item.price && <RichCardPrice>From ${item.price}</RichCardPrice>}
                            </RichCardBody>
                          </RichCard>
                        );
                      })}
                    </RichCards>
                  )}
                </React.Fragment>
              ))}
              {isTyping && (
                <TypingIndicator>
                  <TypingDot />
                  <TypingDot />
                  <TypingDot />
                </TypingIndicator>
              )}
              <div ref={messagesEnd} />
            </Messages>
            {messages.length <= 1 && (
              <QuickWrapper>
                {QUICK_ACTIONS.map((a, i) => (
                  <QuickChip key={i} onClick={() => send(a.message)}>
                    {a.label}
                  </QuickChip>
                ))}
              </QuickWrapper>
            )}
            <InputRow>
              <Input
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && send()}
                placeholder="Ask your digital butler..."
              />
              <SendBtn onClick={() => send()}>Send</SendBtn>
            </InputRow>
          </Panel>
        )}
      </AnimatePresence>

      <FloatBtn
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 1, duration: 0.4 }}
      >
        <ToggleButton onClick={() => setOpen(prev => !prev)} aria-label={open ? 'Close concierge' : 'Open concierge'}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
          </svg>
          {open ? 'Close' : 'Digital Butler'}
        </ToggleButton>
      </FloatBtn>
    </>
  );
}
